// ASSERTION_ENGINE + EVIDENCE_COLLECTOR + REPORT_BUILDER
// input: HTTP fullResponse ($json.statusCode,$json.body) + original test_case ($('TEST_CASE (Webhook)').item.json.body)
const tc = $('TEST_CASE (Webhook)').item.json.body;
const resp = $json;
const status = resp.statusCode || resp.status;
const body = resp.body;
const asserts = [];
for (const rule of (tc.asserts||[])) {
  // rule = {name, path (dot into body), op, value}
  let actual = body;
  for (const k of (rule.path||'').split('.').filter(Boolean)) actual = actual==null?undefined:actual[k];
  let ok=false;
  switch(rule.op){
    case 'status': ok = status === rule.value; actual = status; break;
    case 'eq': ok = actual === rule.value; break;
    case 'exists': ok = actual !== undefined && actual !== null; break;
    case 'gte': ok = Number(actual) >= rule.value; break;
    case 'contains': ok = JSON.stringify(body).includes(rule.value); actual='<body>'; break;
    case 'in': ok = Array.isArray(rule.value) && rule.value.includes(status); actual=status; break;
    default: ok=false;
  }
  asserts.push({name:rule.name, ok, actual});
}
const verdict = asserts.length && asserts.every(a=>a.ok) ? 'PASS' : (asserts.length?'FAIL':'BLOCKED');
return [{ json: { test_case_id: tc.test_case_id, boundary: tc.boundary, verdict, http_status: status, asserts, evidence: { request:{method:tc.method,path:tc.path}, http_status:status, body_excerpt: JSON.stringify(body).slice(0,400) }, observed_at: new Date().toISOString() } }];
